// Official skills, bundled as text (generated from resources/skills/ by
// scripts/bundle-skills.mts — edit the markdown/scripts there, not this file).
//
// They ship enabled; a user skill with the same name shadows one, and any of
// them can be turned off in Settings. Content is procedural knowledge distilled
// from Chaty's own development: the practices that repeatedly separated a fix
// that held from one that had to be redone.

export const OFFICIAL_SKILL_FILES: { file: string; text: string }[] = [
  { file: "cardlet.md", text: "---\nname: cardlet\ndescription: Turn text into polished carousel card images (PNG) via the Cardlet API\nwhen: the user wants social/carousel cards — 小红书图文卡片, Instagram carousel, shareable card decks — from text or notes\n---\n\nCardlet (https://usecardlet.vercel.app) renders styled carousel cards from\nmarkdown-lite text over plain HTTP — bash + curl only, no browser needed.\n\n1. **Write the deck** to `deck.json` in the workspace. `---` splits cards;\n   one idea per card (heading + 1–3 short lines); EN/中文 both render well.\n\n```json\n{\"deck\":{\"t\":\"Title ≤64\",\"b\":\"Intro\\n---\\n## Point one\\nDetail line.\\n---\\n%% 87% | a big stat card\",\"a\":\"@handle\",\"tp\":\"ink\",\"s\":\"ig45\"}}\n```\n\n   Keys: `t` title · `b` body (`## heading`, `- bullet`, `> quote`,\n   `**bold**`, `==highlight==`, `%% stat | caption`, `---` new card) ·\n   `a` author · `tp` template (free: `ink` `cloud` `noir` `peach`) ·\n   `s` size (`ig45` 1080×1350, `xhs34` 小红书 1242×1656, `sq11` square,\n   `story916`) · optional: `f` text size 0–4, `l` spacing 0–2, `bf`\n   `sans`/`serif`, `c` cover card 0/1, `pn` page numbers 1/0.\n\n2. **Render and save** (first call may take 10–20 s — cold start; retry once\n   on failure):\n\n```bash\ncurl -s --max-time 180 -X POST https://usecardlet.vercel.app/api/render \\\n  -H \"Content-Type: application/json\" -d @deck.json \\\n| python3 -c \"import json,sys,base64; d=json.load(sys.stdin); assert 'images' in d, d; [open(f'card-{i+1:02d}.png','wb').write(base64.b64decode(p)) for i,p in enumerate(d['images'])]; print(d['pages'],'cards saved, watermark:',d['watermark'])\"\n```\n\n3. **Report the saved PNG paths** to the user.\n\nLimits: ≤12 cards per JSON call; for bigger decks fetch one card at a time —\n`GET /api/render?d=p<base64url(deckJSON)>&page=N` returns a single binary PNG.\nBe kind to the free API: sequential calls, no parallel bursts.\n\nPro: if the user gives a Cardlet Pro code (`CDLT.…`), add `\"code\":\"CDLT…\"`\nbeside `\"deck\"` — removes the footer watermark and unlocks pro templates\n(`glass` `sunset` `mint` `press` `pop` `night` `terminal` `sakura` `gold`\n`blueprint` `note`) plus `q` (QR sign-off URL). Without a code, cards carry a\nsmall watermark — say so instead of working around it.\n" },
  { file: "debug-by-mechanism.md", text: "---\nname: debug-by-mechanism\ndescription: Find the mechanism behind a bug instead of pattern-matching a fix\nwhen: something is broken, failing, or behaving unexpectedly\n---\n\nA fix that makes the symptom disappear without explaining it usually moved the\nbug somewhere quieter.\n\n1. **Reproduce it smaller.** Strip the case until one more removal makes the\n   symptom vanish. That boundary is where the mechanism lives.\n2. **Read the code on the failing path** — the actual current source, not your\n   memory of it. Note every place the observed value could come from.\n3. **Name the mechanism in one sentence** before editing anything: \"X happens\n   because Y runs before Z.\" If you can't, you're still guessing.\n4. **Predict something else that must be true** if your explanation is right,\n   then check it. A wrong theory usually fails this step, cheaply.\n5. **Fix the mechanism, not the symptom.** Then confirm the original case, and\n   confirm a neighbouring case that shares the mechanism.\n6. **If two attempts fail**, the mechanism is wrong — go back to step 2 rather\n   than layering another guess on top.\n" },
  { file: "debug-playbook.md", text: "---\nname: debug-playbook\ndescription: Pick the RIGHT debug method for the failure you actually have — compile, crash, wrong output, dead UI — on any stack\nwhen: a build fails, an app crashes or misbehaves, output is wrong, tests are red, or you are about to deliver an app whose functions you have not exercised\n---\n\nMatch the method to the symptom. Re-running the same command and hoping is\nnever a method.\n\n## 1. Compile / build error\nRead the FIRST `file:line` in the output → `read_file` that spot → fix that\none error → rebuild. Repeat one error at a time. Never re-run an unchanged\nbuild; never \"fix\" files the error doesn't name.\n\n## 2. Crash at runtime\nRun the thing in the foreground and read the top stack frame that is in\nYOUR code (not the framework). Crash on launch with no output → run the\nbinary directly (not via `open`) to see stderr.\n\n## 3. Wrong behavior / logic bug\nWrite a minimal failing test FIRST — one that states the expected result —\nthen fix until it passes. Keep the test. This is faster than print-guessing,\nand it becomes your functional proof at delivery.\n\n## 4. Per-stack functional verification (the delivery bar)\nCompiling and launching is the entry ticket, not the goal — every basic\nfunction must be EXECUTED before delivery:\n\n- **CLI tool**: run it with real inputs for every subcommand/flag you\n  implemented; check the actual output, including the error paths\n  (missing file, bad args).\n- **Web app**: start the dev server, `browser_navigate`, and CLICK through\n  every feature — add/edit/delete/toggle, then reload to prove persistence.\n  Watch `[console]` errors in tool results.\n- **HTTP API**: `curl -f` every endpoint (or print `-w '%{http_code}'` and\n  read it) — plain curl exits 0 on a 404, so without `-f` your\n  \"verification\" verifies nothing. Cover happy path AND a 404/400 case,\n  check the JSON body, and remember route params arrive as STRINGS —\n  compare with `String(id)` / cast before `===`.\n- **Native GUI (SwiftUI …)**: UI can't be clicked headlessly, so structure\n  for testability: core logic (state, storage, calculations) lives in plain\n  types, views stay thin. Write tests for that core and run `swift test`\n  (SwiftPM layout: `Tests/<Name>Tests/`). Launch + stay-alive covers the\n  shell; the tests cover the functions.\n- **Library/module**: its test suite IS the functional bar — every public\n  function gets at least one test.\n\n## 5. When a command is DENIED\n\"Operation not permitted\" on a build/cache path → workspace-relative paths;\nscreen/automation denials are macOS TCC, not the sandbox — verify another\nway, never abandon the stack over it.\n\n## Delivery rule\nFor each basic function, name in your final answer HOW it was verified\n(test name, click path, or the exact command + output). A function with no\nexecuted proof is not done. After verifying, CLEAN UP your test artifacts —\nsample records, scratch files, seeded data — so the user receives a fresh\nstate, and note the cleanup in your answer.\n" },
  { file: "investigate-first.md", text: "---\nname: investigate-first\ndescription: Understand an unfamiliar codebase before changing it\nwhen: starting work in a repo or area you haven't touched yet\n---\n\n1. **Orient once**: `understand_repo` for the shape, then read the build/test\n   commands. Knowing how to run the tests early is what makes every later step\n   verifiable.\n2. **Search by meaning, not by guess**: `search_code` with the behavior you're\n   looking for (\"where uploads are validated\"), then `outline` the files it\n   returns before reading them whole.\n3. **Follow the data, not the names.** Find where the value you care about is\n   produced and where it is consumed; the code in between is the part you\n   actually need to understand.\n4. **Match local conventions** — comment density, naming, error handling. A\n   change that reads like the file around it needs no explanation.\n5. **Check for existing tests of the area** before writing new ones; extend\n   the established pattern rather than introducing a second style.\n" },
  { file: "mac-app.md", text: "---\nname: mac-app\ndescription: Build a runnable macOS .app the incremental way — feature, verify, next feature — and package + launch-check before delivering\nwhen: the user asks for a macOS desktop app (mac 桌面应用/日历/记事本/工具类 GUI) — the deliverable must be a packaged .app that actually launches, not just source files\n---\n\nThe deliverable is a **double-clickable .app that launches and works** — source\nthat merely compiles is half the job. Work in this exact rhythm:\n\n1. **Skeleton first, verify immediately.** Scaffold the smallest thing that\n   builds AND launches (empty window is fine). Package it, launch it, kill it.\n   Only then start features.\n2. **One feature at a time.** Implement → `validate_change` (or the build\n   command) → green → next feature. Never stack 4+ unverified files.\n3. **Never break green.** After a red result, suspect ONLY what you changed\n   since the last green check; restore it if needed. Do not \"improve\" code\n   that already passed — no renames, no restructuring, no style edits of\n   working files.\n\n## SwiftUI + SwiftPM (the ONLY supported scaffold here)\n\n**Never hand-write an `.xcodeproj`.** A hand-made `project.pbxproj` is\nalmost always malformed — unreadable by xcodebuild, wrong file references,\nbroken resource paths (this audit hit all three). SwiftPM gives you build,\ntests, and packaging with zero project files; editing an .xcodeproj is only\nfor projects that already ship one.\n\nLayout: `Package.swift` + `Sources/<Name>/…` with an `@main` SwiftUI `App`.\nDeclare the platform UP FRONT — `platforms: [.macOS(.v14)]` — modern SwiftUI\nAPIs (`ContentUnavailableView`, …) are macOS 14+, and an availability error\ndiscovered late forces a rewrite you have no budget for. If one still\nappears, RAISE the platform version; never rewrite working views around it.\nBuild, package, and launch-check:\n\n```bash\nswift build -c release 2>&1 | tail -5\nAPP=\"<Name>.app\"; BIN=\".build/release/<Name>\"\nmkdir -p \"$APP/Contents/MacOS\" && cp \"$BIN\" \"$APP/Contents/MacOS/<Name>\"\nprintf '<?xml version=\"1.0\" encoding=\"UTF-8\"?><!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\"><plist version=\"1.0\"><dict><key>CFBundleExecutable</key><string><Name></string><key>CFBundleIdentifier</key><string>local.<name></string><key>CFBundleName</key><string><Name></string><key>CFBundlePackageType</key><string>APPL</string><key>NSHighResolutionCapable</key><true/></dict></plist>' > \"$APP/Contents/Info.plist\"\n\"$APP/Contents/MacOS/<Name>\" & APP_PID=$!; sleep 4\nkill -0 $APP_PID && echo \"LAUNCH OK (alive after 4s)\" || echo \"LAUNCH FAILED — fix before delivering\"\nkill $APP_PID 2>/dev/null\n```\n\n`LAUNCH FAILED` usually means a crash at startup — run the binary in\nforeground briefly to read the crash text.\n\n## Electron / web-view stack\n\n`electron-builder --dir` (never full dmg — slow) puts the bundle under\n`dist/mac*/<Name>.app`; launch-check the same way with\n`dist/mac*/<Name>.app/Contents/MacOS/<Name>`. Remember: production must\n`loadFile('dist/index.html')` — verify AFTER `vite build`, not against the\ndev server only.\n\n## SwiftUI patterns that break small models (copy these, don't improvise)\n\n**Editable list items** — inside `List`/`ForEach` the element is a VALUE\ncopy; you cannot make a `Binding` from it. Iterate the binding collection:\n\n```swift\nList { ForEach($store.notes) { $note in\n    TextField(\"标题\", text: $note.title)   // $note IS a Binding\n} .onDelete { store.notes.remove(atOffsets: $0) } }\n```\n\n**Master–detail editor** — select by id, edit through a computed binding:\n\n```swift\nList(store.notes, selection: $selectedID) { note in Text(note.title) }\nif let i = store.notes.firstIndex(where: { $0.id == selectedID }) {\n    NoteEditor(note: $store.notes[i])\n}\n```\n\n## Verification truths (don't learn these the hard way)\n\n- **Browser screenshot ≠ system screenshot.** `browser_screenshot` captures\n  the embedded browser's web page only — it can never show a native window.\n  Native GUI proof = the launch + stay-alive check above.\n- **\"Operation not permitted\" is usually NOT the sandbox.** The sandbox only\n  blocks writes outside the workspace. Screen recording (`screencapture`)\n  and app automation (`osascript` → other apps) fail on macOS *privacy\n  authorization* (TCC) — do not abandon the task or switch stacks over it;\n  verify without that permission instead.\n- **One stack, start to finish.** If you must switch stacks, say why and\n  delete the old implementation — never leave two half-apps in the tree.\n\n## Functional bar: launching is not \"working\"\n\nStructure for testability from the first file: **core logic in plain types**\n(state machines, stores, calculations — no SwiftUI imports), views thin.\nAdd a test target and exercise every basic function:\n\n```\nTests/<Name>Tests/CoreTests.swift   // import XCTest + @testable import <Name>\nswift test 2>&1 | tail -3           // must end \"0 failures\"\n```\n\n**Use THREE targets** — tests must depend on a library, never on the\nexecutable (linking an `@main` target into tests duplicates `_main`):\n\n```swift\n// swift-tools-version:5.9\nimport PackageDescription\nlet package = Package(\n    name: \"<Name>\", platforms: [.macOS(.v14)],\n    targets: [\n        .target(name: \"<Name>Core\"),                                // logic — testable\n        .executableTarget(name: \"<Name>\", dependencies: [\"<Name>Core\"]), // @main + views\n        .testTarget(name: \"<Name>CoreTests\", dependencies: [\"<Name>Core\"]),\n    ]\n)\n```\n\nTwo rules make the split work — missing either is the #1 multi-target\nfailure (\"cannot find 'X' in scope\"):\n1. **Everything in Core is `public`**: `public struct Note`, `public class\n   NoteStore`, `public init(...)`, `public func …`, `@Published public var …`.\n2. **Every file in the executable target starts with `import <Name>Core`.**\nTest the real flows: add → edit → delete → reload/persist round-trip, plus\none edge case each (empty input, missing file). A feature without a passing\ntest or an executed proof is not done.\n\n**After your LAST source edit, the packaging pipeline runs AGAIN** —\nrebuild (`swift build -c release`; `swift test` only refreshes DEBUG\nproducts, never the release binary) → re-copy into the `.app` → re-run the\nlaunch check. An `.app` packaged before your final fix ships the bug you\njust fixed.\n\n## Delivery checklist (all five, in the answer)\n\n- build green (real build, not `-parse`/`--version`)\n- `swift test` green with the core functions covered\n- `.app` bundle exists in the workspace\n- launch check printed `LAUNCH OK`\n- each claimed feature names its proof (test name or executed command)\n" },
  { file: "tiktok-video/SKILL.md", text: "---\nname: tiktok-video\ndescription: 一句话需求 → 成品竖屏短视频:写分镜、自动搜免费素材、TTS 配音、逐字卡拉OK字幕、BGM、ffmpeg 合成 1080x1920 MP4(零 API key 可用)\nwhen: the user asks to create / make / generate a short video(做短视频/抖音视频/TikTok/Shorts/Reels)on any topic\n---\n\n# TikTok / 抖音短视频生成\n\n你做**创意**部分——文案、分镜、搜索关键词、质量审查;`{SKILL_ROOT}/scripts/` 里的脚本做**机械**部分——TTS 逐字时间戳、素材搜索下载、字幕渲染、ffmpeg 合成、响度标准化。脚本已随 Chaty 就位,勿重写。\n\n前置:`ffmpeg` + `python3` 在 PATH(macOS: `brew install ffmpeg`;Windows 需 Git Bash,且下文的 `.venv/bin/python` 换成 `.venv/Scripts/python`)。零 API key 即可跑;环境变量 `PEXELS_API_KEY` / `PIXABAY_API_KEY`(免费申请)可解锁实拍视频片段,有则优先。\n\n## 0. 一次性安装(若 `{SKILL_ROOT}/.venv` 已存在则跳过)\n\n```bash\nbash {SKILL_ROOT}/scripts/setup.sh\n```\n\n## 1. 先核实,再写文案 + 分镜\n\n**模型的内部知识可能过期或有错——未经核实的论断禁止进视频。**动笔前用你的联网搜索工具核实文案里每一个具体论断:数字、统计、纪录、价格、日期、排名、一切\"第一/最大/唯一/最快\",以及任何时效性内容(新闻/产品/版本/\"今年/最新\"),无论你多有把握。规则:**按来源改写文案**(不是反过来);核实不了就换成能核实的或直接删;把依据的 URL 记入 storyboard 的 `\"sources\": [...]`(会出现在 report.txt 供用户复核);确实无联网能力时只用教科书级常识、避免具体数字、并向用户声明未核实。\n\n然后读 `{SKILL_ROOT}/references/writing-guide.md`(hook 公式、节奏、场景结构)。然后在工作区建 `<slug>/storyboard.json`:\n\n```json\n{\n  \"title\": \"深海里最诡异的3种生物\",\n  \"lang\": \"zh\",\n  \"aspect\": \"9:16\",\n  \"voice\": \"zh-CN-YunjianNeural\",\n  \"rate\": \"+10%\",\n  \"caption_style\": \"karaoke\",\n  \"bgm\": {\"mood\": \"mystery\", \"gain_db\": -16},\n  \"hook\": {\"text\": \"深海禁区\", \"seconds\": 2.3},\n  \"scenes\": [\n    {\n      \"text\": \"你知道吗?在阳光永远照不到的深海,藏着比科幻电影更诡异的生物。\",\n      \"keywords\": [\"deep sea NOAA ocean exploration\", \"submarine dark ocean\"],\n      \"providers\": [\"openverse\", \"wikimedia\"],\n      \"effect\": \"kb_in\"\n    },\n    {\n      \"text\": \"第一名,鮟鱇鱼。头顶挂着一盏会发光的钓鱼灯,守在黑暗里等猎物送上门。\",\n      \"keywords\": [\"humpback anglerfish\", \"anglerfish museum\"],\n      \"badge\": \"第1名\"\n    }\n  ]\n}\n```\n\n字段速查:\n\n| 字段 | 取值 | 说明 |\n|---|---|---|\n| `lang` | `zh` \\| `en` | 决定字幕分组和默认音色 |\n| `aspect` | `9:16`(默认) \\| `16:9` \\| `1:1` | |\n| `voice` | 任意 edge-tts 音色 | zh: `zh-CN-YunjianNeural`(磁性男) `zh-CN-XiaoxiaoNeural`(女) `zh-CN-YunxiNeural`(阳光男);en: `en-US-ChristopherNeural` `en-US-AriaNeural` |\n| `rate` | 如 `+10%` | 营销号节奏:zh `+8%`~`+15%`,en `+5%`~`+10%` |\n| `caption_style` | `karaoke` \\| `pop` \\| `none` | karaoke = 逐字高亮(推荐) |\n| `bgm` | `{\"query\":\"风格词\"}` \\| `{\"mood\":…}` \\| `{\"file\":\"路径\"}` \\| `{\"mood\":\"none\"}` | **默认选 `mood`**:曲表(upbeat funny inspiring chill tech mystery epic sad horror)是无数营销号在用的 MacLeod 熟脸配乐,按项目随机换曲;**表内没有贴合风格的才用 `query` 搜**(ccMixter/Jamendo CC 曲,节拍器自动筛掉没鼓点的):盘点/悬念 `\"trap\"`、种草 `\"lofi chill\"`、励志 `\"epic cinematic\"`、搞笑 `\"quirky\"`;两者可同设(query 先试、mood 兜底);热门歌用 `file`(版权自负)|\n| `beat_sync` | `true`(默认) \\| `false` | BGM 自动节拍分析,所有切镜吸附到节拍上(卡点);人声永不截断,只伸缩场景尾部留白;鼓点弱的曲子会自动跳过 |\n| `bgm.vibe` | `\"spedup\"` \\| `\"slowed\"` \\| 不设 | 抖音标志性音色:spedup ≈1.25×提速升调(卡点/盘点主流),slowed = 减速+混响(情感向);任何 bgm 来源都可加,处理后自动重测节拍 |\n| `hook` | `{\"text\",\"seconds\"}` | 开头大字标题卡,≤8 字/词 |\n| `sticky_title` | `{\"text\":…}` | 可选的顶部常驻话题条;默认关,用户要才加 |\n| `sfx` | `true`(默认) \\| `false` | 转场 whoosh 音效 |\n| 场景 `keywords` | **英文、具体名词**的列表 | **每条 = 一个镜头画面**;视频约每 3s 切一镜,场景超过 ~4s 就给 2–3 条(给少了会循环补拍) |\n| 场景 `badge` | 如 `\"第1名\"` / `\"TOP 1\"` | 场景开头的大号盖章标签,榜单类必用 |\n| 场景 `providers` | 列表 | 免 key:`openverse` `wikimedia` `nasa`;有 key:`pexels_video` `pexels_photo` `pixabay_video` |\n| 场景 `effect` | `auto` `kb_in` `kb_out` `pan_left` `pan_right` `static` | 第一镜的 Ken Burns 动效,后续镜头自动轮换 |\n| 场景 `media` | 文件路径 | 跳过搜索,用你自己准备的素材 |\n\n**经验值(发布线):总长 45–75s、6–9 个场景、每场景一个观点、2–3 个镜头。**文案中文 20–45 字 / 英文 14–30 词。低于 ~40s 或全程单镜头会显单薄,别交付。\n\n## 2. 跑管线\n\n```bash\n{SKILL_ROOT}/.venv/bin/python {SKILL_ROOT}/scripts/pipeline.py <slug>\n```\n\n也可分段:`tts.py` → `assets.py` → `bgm.py` → `compose.py` → `check.py`(都接 `<slug>` 参数)。改过 storyboard 后重合成很快:`pipeline.py <slug> --skip-tts --skip-assets`;但改了场景**文案**必须重跑 `tts.py`。\n\n## 3. 审查——质量分水岭(必做)\n\n免费图片搜索不完美,**像人类编辑一样审**:\n\n1. assets 阶段后用 `view_image` 看 `<slug>/media/assets_sheet.jpg`。镜头标号 `01a 01b 02a…`,任何一镜与文案不符就换词重搜:\n\n   ```bash\n   {SKILL_ROOT}/.venv/bin/python {SKILL_ROOT}/scripts/assets.py <slug> --scene 3 --shot 2 --keywords \"better english nouns\"\n   ```\n\n   (重搜自动拉黑被否素材,重复到全部匹配;也可自己下载图片后把场景 `media` 指向它。)**目检确认**某个被 `[!]` 标记的镜头其实没问题时(如无描述标题的好图),在 `media/manifest.json` 给该 shot 加 `\"approved\": true` 消除误报——眼见优先于文本审计,严禁盲批。\n\n2. compose+check 后用 `view_image` 看 `<slug>/review/contact_sheet.jpg`:字幕可读且同步、无错帧丑帧、hook 可见。有问题就改 storyboard 重合成,直到像营销号编辑敢发的成片。\n\n`assets.py` 和 `check.py` 都会自动比对每格素材的来源标题和场景关键词,跑题的直接打 `[!] OFF-TOPIC` 并给出重搜命令(assets 阶段就 flag,别等合成完)——**任何 `[!]` 都必须处理完才能交付**。若你无法真正看到图片(非视觉模型),这些标题 flag 就是你的审查:重搜 → `--skip-tts --skip-assets` 重合成 → 重跑 check,直到零 `[!]`。\n\n`review/report.txt` 含时长/响度检查和**素材署名文本**(CC-BY 来源 + 音乐 credit)——连同 `final.mp4` 一并交给用户。\n\n## 搜索技巧(最大质量杠杆)\n\n- 关键词必须**英文**、1–4 词、**具体可见的名词**(\"humpback anglerfish\"、\"scuba diver silhouette\"),忌抽象概念(\"mystery\"、\"success\")。\n- `wikimedia` 擅长动物/科学/历史/地标;`openverse`(Flickr 等)擅长生活方式/风景/氛围;`nasa` 管太空;有 key 优先 `pexels_video`/`pixabay_video` 实拍。\n- 加语境词消歧:\"NOAA\"、\"museum\"、\"aquarium\"、\"macro\"。\n- 某场景反复搜不到就换**视觉概念**而不只是换词(讲\"仅5%被探索\"→拍剪影潜水员,别搜\"statistics\")。\n\n## 排障\n\n- edge-tts 网络错误:自带 4 次重试,仍失败就重跑 `tts.py`。\n- BGM 下载失败:重跑 `bgm.py`(有缓存),或 `\"mood\":\"none\"`,或放一个 mp3 到 `{SKILL_ROOT}/assets/bgm/` 并用 `bgm.file` 指向它。\n- 单个 provider 报错/空结果无妨,其余会补位;看每场景日志。\n- 字幕 emoji 仅 macOS 可渲染,别用 emoji 承载语义。\n\n## 交付\n\n给用户:`<slug>/final.mp4` + `report.txt` 里的署名文本;若要封面给 `<slug>/review/cover.jpg`。\n" },
  { file: "verify-before-push.md", text: "---\nname: verify-before-push\ndescription: Prove a change works before it leaves the machine\nwhen: the user asks to commit, push, or ship a change\n---\n\nNever push a change whose correctness you have only reasoned about.\n\n1. **Pick the gate that can actually fail.** Type-checkers and linters catch\n   shape errors, not behavior. If the change alters behavior, the gate is a\n   test that fails without your fix and passes with it — write it if it\n   doesn't exist.\n2. **Run the gate and read the output.** Do not infer success from \"no error\n   printed\"; find the pass count or the assertion that proves the new path ran.\n3. **For anything visual or interactive**, capture evidence: a screenshot,\n   a measured pixel value, a page digest. A description of what should happen\n   is not evidence.\n4. **Commit only after the gate is green**, and put what you verified in the\n   commit message — the next reader needs to know which claims were checked.\n5. **If a gate can't be run locally** (another OS, real credentials, a GPU),\n   say so plainly and name what remains unverified. Do not present it as done.\n" },
];

